let chapterObserver;
let stopFlowerMotion;
let lang=new URLSearchParams(location.search).get('lang')==='en'?'en':'ru';
const isCase=location.pathname.endsWith('finelo.html');
function keepPrepositions(text){
  const words=lang==='ru'?'а|без|в|во|для|до|за|и|из|из-за|из-под|или|к|ко|между|на|над|не|но|о|об|обо|от|перед|по|под|при|про|с|со|у|через':'a|an|the|at|by|for|from|in|of|on|to|with';
  const shortWord=new RegExp(`(^|[\\s(«„“])(${words})[ \t]+(?=\\S)`,'giu');
  return text.split(/(<[^>]*>)/g).map(part=>part.startsWith('<')?part:part.replace(shortWord,'$1$2\u00a0').replace(shortWord,'$1$2\u00a0')).join('');
}
const t=(ru,en)=>keepPrepositions(lang==='ru'?ru:en);
const href=(page,hash='')=>`${page}?lang=${lang}&v=14${hash}`;
const externalArrow=`<svg class="external-arrow" viewBox="0 0 20 20" fill="none" aria-hidden="true"><path d="M4 16 16 4M4 4h12v12"/></svg>`;
