function header(){return `<a class="skip" href="#main">${t('К содержанию','Skip to content')}</a><div class="header-shell"><header class="header wrap"><a class="wordmark" href="${href('index.html')}" aria-label="${t('Люда Запевалова — главная','Lyudmila Zapevalova — home')}"><span class="avatar" aria-hidden="true"><span class="avatar-clip"><img src="assets/lyudmila-portrait.jpeg" alt="" width="1010" height="1468"></span>${avatarFlower}</span><span class="brand-name">${t('Люда Запевалова','Lyudmila Zapevalova')}</span></a><nav class="nav" aria-label="${t('Основная навигация','Main navigation')}"><div class="nav-links"><a href="${href('index.html','#work')}">${t('Проекты','Projects')}</a><a href="${href('index.html','#about')}">${t('Обо мне','About')}</a><a href="#contact">${t('Связаться','Contact')}</a><a href="assets/Lyudmila-Zapevalova-CV.pdf" target="_blank">${t('Резюме','CV')}</a></div><div class="languages" aria-label="${t('Язык сайта','Site language')}"><button data-lang="ru" aria-pressed="${lang==='ru'}">RU</button><button data-lang="en" aria-pressed="${lang==='en'}">EN</button></div></nav></header></div>`}
function footer(){return `<footer class="footer" id="contact"><div class="wrap"><div class="footer-main"><div><h2>${t('Открыта к новым<br>проектам и сотрудничеству.','Open to new projects<br>and collaboration.')}</h2><div class="contact-links"><a href="mailto:l.zapevalova@gmail.com">Email ${externalArrow}</a>${external('https://t.me/l_zapevalova','Telegram')}${external('https://www.behance.net/lyudazapevalova','Behance')}${external('https://www.linkedin.com/in/lyudmila-zapevalova/','LinkedIn')}<a href="assets/Lyudmila-Zapevalova-CV.pdf" target="_blank">${t('Резюме','CV')} ${externalArrow}</a></div></div><a class="text-link" href="#top">${t('Наверх','Back to top')} ↑</a></div><div class="footer-meta"><span>© 2026 ${t('Люда Запевалова','Lyudmila Zapevalova')}</span><span>${t('Алматы, Казахстан','Almaty, Kazakhstan')}</span></div></div></footer>`}
